163	              onDelete();
164	            }}
165	            className={styles.deleteBtn}
166	          >
167	            Delete note
168	          </button>
169	        </div>
170	      )}
171	    </div>
172	  );
173	
174	  if (!expanded) {
175	    return (
176	      <div
177	        className={`${styles.card} ${styles.collapsed}`}
178	        data-color={note.color}
179	      >
