1	/* Persistent right-column notes panel on the admin editor.
2	
3	   Wide screens (>=1100px): inline in the page grid, sticky so it
4	     stays visible while the writer scrolls a long body.
5	   Narrow screens (<1100px): hidden by default; revealed as a
6	     slide-in sheet from the right when the FAB is tapped. */
7	
8	.panel {
9	  display: flex;
10	  flex-direction: column;
11	  gap: 12px;
12	  align-self: start;
13	  /* Wider than the original 340px so the panel absorbs the empty
14	     space between ContentForm's 1200px max-width and the right
15	     viewport edge on standard desktop widths. */
16	  width: clamp(360px, 32vw, 600px);
17	  max-height: calc(100dvh - 96px);
18	  padding: 14px;
19	  background: var(--bg-surface);
20	  border: 1px solid var(--border-line);
21	  border-radius: var(--radius-md-app);
22	  position: sticky;
23	  top: 24px;
24	  font-family: var(--font-ui);
25	  /* Silky expand/collapse — ease-out-quart is the curve that reads
26	     as "natural deceleration", not "linear lerp". Includes
27	     min-height (PR #180 added it) so growth and shrink are paired. */
28	  transition:
29	    max-height 260ms cubic-bezier(0.16, 1, 0.3, 1),
30	    min-height 260ms cubic-bezier(0.16, 1, 0.3, 1),
31	    top 260ms cubic-bezier(0.16, 1, 0.3, 1);
