56	interface Props {
57	  tags: Tag[];
58	  /** Active tag ids — these get the gold-stroke active state */
59	  activeIds?: string[];
60	  /** Base href for tag links (e.g., "/search") */
61	  basePath?: string;
62	  /** Existing search query to preserve when clicking tags */
63	  search?: string;
64	  /** Threshold below which the toggle button stays hidden */
65	  expandThreshold?: number;
66	}
67	
68	/**
69	 * Tag filter bar.
70	 *
71	 * Default: single-line horizontal scroll with a fade on the right edge.
72	 * Expanded: tags are grouped by their first letter (A, B, C...) so a
73	 * 500-tag taxonomy stays browseable. Each letter is a row with the
74	 * letter on the left and pills wrapping to the right.
75	 *
76	 * Color rules:
77	 *   - safe tag (isAdult = false)  -> green pill
78	 *   - adult tag (isAdult = true)  -> red pill
79	 *   - selected (active) tag       -> gold border, regardless
80	 */
81	export default function TagBar({
82	  tags,
83	  activeIds,
84	  basePath = "/search",
85	  search,
86	  expandThreshold = 12,
87	}: Props) {
88	  const [expanded, setExpanded] = useState(false);
89	  const activeSet = useMemo(() => new Set(activeIds ?? []), [activeIds]);
90	  const showToggle = tags.length > expandThreshold;
91	
92	  const allHref = search
93	    ? `${basePath}?search=${encodeURIComponent(search)}`
94	    : basePath;
95	
96	  const buildTagHref = (tagId: string) => {
97	    const params = new URLSearchParams();
98	    if (search) params.set("search", search);
99	    params.set("tagIds", tagId);
100	    return `${basePath}?${params.toString()}`;
101	  };
102	
103	  const sortedTags = useMemo(
104	    () => [...tags].sort((a, b) => a.name.localeCompare(b.name)),
105	    [tags],
106	  );
107	
108	  // Group expanded tags by first letter for browsability.
109	  const grouped = useMemo(() => {
110	    const map = new Map<string, Tag[]>();
111	    for (const tag of sortedTags) {
112	      const ch = tag.name.charAt(0);
113	      const key = ch ? (/[a-z]/i.test(ch) ? ch.toUpperCase() : "#") : "#";
114	      const list = map.get(key) ?? [];
115	      list.push(tag);
116	      map.set(key, list);
117	    }
118	    return Array.from(map.entries()).sort(([a], [b]) => {
119	      if (a === "#") return 1;
120	      if (b === "#") return -1;
121	      return a.localeCompare(b);
122	    });
123	  }, [sortedTags]);
124	
125	  if (tags.length === 0) return null;
126	
127	  if (expanded) {
128	    return (
129	      <div className={styles.wrapper}>
130	        <div className={styles.collapseRow}>
131	          <button
132	            type="button"
133	            onClick={() => setExpanded(false)}
134	            className={styles.toggle}
135	            // Explicit boolean — `aria-expanded` without a value
136	            // renders as the empty string, which some screen readers
137	            // misinterpret. The collapsed-row button below uses
138	            // `aria-expanded={false}` so this mirror is consistent.
139	            aria-expanded={true}
140	          >
141	            Collapse
142	            <Chevron open />
143	          </button>
144	        </div>
145	
146	        <div className={styles.expanded}>
147	          {/* "All" stays at the top */}
148	          <div className={styles.letterGroup}>
149	            <span className={styles.letter} aria-hidden>·</span>
150	            <div className={styles.letterPills}>
151	              <Link
152	                href={allHref}
153	                className={`${styles.pill} ${activeSet.size === 0 ? styles.pillActive : ""}`}
154	              >
155	                All
156	              </Link>
157	            </div>
158	          </div>
159	
160	          {grouped.map(([letter, letterTags]) => (
161	            <div key={letter} className={styles.letterGroup}>
162	              <span className={styles.letter}>{letter}</span>
163	              <div className={styles.letterPills}>
164	                {letterTags.map((tag) => (
165	                  <Pill
166	                    key={tag.id}
167	                    tag={tag}
168	                    href={buildTagHref(tag.id)}
169	                    active={activeSet.has(tag.id)}
170	                  />
171	                ))}
172	              </div>
173	            </div>
174	          ))}
175	        </div>
176	      </div>
177	    );
178	  }
179	
180	  // Collapsed (default): single horizontal-scroll row.
181	  return <CollapsedRow
182	    sortedTags={sortedTags}
183	    allHref={allHref}
184	    activeSet={activeSet}
185	    buildTagHref={buildTagHref}
186	    showToggle={showToggle}
187	    onExpand={() => setExpanded(true)}
188	  />;
189	}
