191	function CollapsedRow({
192	  sortedTags,
193	  allHref,
194	  activeSet,
195	  buildTagHref,
196	  showToggle,
197	  onExpand,
198	}: {
199	  sortedTags: Tag[];
200	  allHref: string;
201	  activeSet: Set<string>;
202	  buildTagHref: (id: string) => string;
203	  showToggle: boolean;
204	  onExpand: () => void;
205	}) {
206	  const listRef = useRef<HTMLDivElement>(null);
207	  // Drives the data-scroll attribute on the list, which the CSS
208	  // uses to pick a mask-image (left fade / right fade / both /
209	  // none) per the row's current scroll position.
210	  const edge = useScrollEdges(listRef);
211	
212	  return (
213	    <div className={styles.wrapper}>
214	      <div className={styles.row}>
215	        <div ref={listRef} className={styles.list} data-scroll={edge}>
216	          <Link
217	            href={allHref}
218	            className={`${styles.pill} ${activeSet.size === 0 ? styles.pillActive : ""}`}
219	          >
220	            All
221	          </Link>
222	          {sortedTags.map((tag) => (
223	            <Pill
224	              key={tag.id}
225	              tag={tag}
226	              href={buildTagHref(tag.id)}
227	              active={activeSet.has(tag.id)}
228	            />
229	          ))}
230	        </div>
231	
232	        {showToggle && (
233	          <button
234	            type="button"
235	            onClick={onExpand}
236	            className={styles.toggle}
237	            aria-expanded={false}
238	          >
239	            All tags
240	            <Chevron open={false} />
241	          </button>
242	        )}
243	      </div>
244	    </div>
245	  );
246	}
