248	function Pill({
249	  tag,
250	  href,
251	  active,
252	}: {
253	  tag: Tag;
254	  href: string;
255	  active: boolean;
256	}) {
257	  const variant = tag.isAdult ? styles.pillAdult : styles.pillSafe;
258	  const activeCls = active ? styles.pillActive : "";
259	  return (
260	    <Link
261	      href={href}
262	      className={`${styles.pill} ${variant} ${activeCls}`}
263	      title={tag.isAdult ? `${tag.name} (adult)` : tag.name}
264	    >
265	      {tag.name}
266	    </Link>
267	  );
268	}
