8	/**
9	 * Grid wrapper for sections that should fill the container width
10	 * (auto-fill, minmax(280px, 1fr)). Same GSAP stagger reveal as CardRow
11	 * so the visual rhythm matches.
12	 */
13	export default function CardGrid({ children }: { children: React.ReactNode }) {
14	  const containerRef = useRef<HTMLDivElement>(null);
15	
16	  useGSAP(
17	    () => {
18	      if (!containerRef.current) return;
19	      if (prefersReducedMotion()) return;
