29	        scrollTrigger: {
30	          trigger: containerRef.current,
31	          start: "top 85%",
32	          once: true,
33	        },
34	      });
35	    },
36	    { scope: containerRef },
37	  );
38	
39	  void ScrollTrigger;
40	
41	  return (
42	    <div ref={containerRef} className={styles.grid}>
43	      {children}
44	    </div>
