18	 * Clicking "See all" flips the layout to a multi-row grid in place,
19	 * showing every card without leaving the page. "Collapse" returns to
20	 * the row.
21	 */
22	export default function ExpandableSection({
23	  title,
24	  children,
25	  expandable = true,
26	}: Props) {
27	  const [expanded, setExpanded] = useState(false);
28	  const containerRef = useRef<HTMLDivElement>(null);
29	
30	  useGSAP(
31	    () => {
32	      if (!containerRef.current) return;
33	      if (prefersReducedMotion()) return;
34	      const cards = Array.from(containerRef.current.children);
35	      if (cards.length === 0) return;
36	      // Fade-only — earlier we also translated each card up from y:30,
37	      // but during the staggered reveal that produces a brief moment
38	      // where cards land at uneven heights. Opacity stagger reads as
