41	        opacity: 0,
42	        stagger: 0.06,
43	        duration: 0.4,
44	        ease: "power2.out",
45	        scrollTrigger: {
46	          trigger: containerRef.current,
47	          start: "top 85%",
48	          once: true,
49	        },
50	      });
51	    },
52	    { scope: containerRef, dependencies: [] },
53	  );
54	
55	  // The import side-effect registers the plugin via lib/gsap.ts.
56	  void ScrollTrigger;
57	
58	  return (
